<script setup>
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { authState } from '../../services/authService'
import { getSurvey, saveSurvey } from '../../services/surveyService'
import minimalistImg from '../../assets/images/survey/minimalist.jpg'
import streetwearImg from '../../assets/images/survey/streetwear.jpg'
import vintageImg from '../../assets/images/survey/vintage.jpg'
import y2kImg from '../../assets/images/survey/y2k.jpg'
import preppyImg from '../../assets/images/survey/preppy.jpg'
import classicImg from '../../assets/images/survey/classic.jpg'
import romanticImg from '../../assets/images/survey/romantic.jpg'

const router=useRouter()
const styleOptions=[
 {name:'Minimalist',desc:'Clean lines, neutrals, simple silhouettes',image:minimalistImg},
 {name:'Streetwear',desc:'Relaxed shapes, sneakers, graphic layers',image:streetwearImg},
 {name:'Vintage',desc:'Retro details, nostalgic prints, timeless finds',image:vintageImg},
 {name:'Y2K',desc:'Playful 2000s shapes, denim, fitted silhouettes',image:y2kImg},
 {name:'Preppy',desc:'Polished classics, knits and skirts',image:preppyImg},
 {name:'Classic',desc:'Tailored, refined and easy to dress up',image:classicImg},
 {name:'Romantic',desc:'Soft colours, feminine details and flowy shapes',image:romanticImg}
]
const activities=['University','Presentation','Interview','Date','Internship / work','Casual outings','Formal events']
const selectedStyles=ref([]),selectedActivities=ref([]),budget=ref(40),busy=ref(false),loading=ref(true),error=ref('')
const previewStyles=computed(()=>selectedStyles.value.length?selectedStyles.value:['Your style'])
const previewHeadline=computed(()=>{
  if(!selectedStyles.value.length) return 'Your style mix'
  if(selectedStyles.value.length <= 2) return selectedStyles.value.join(' + ')
  return `${selectedStyles.value.slice(0,2).join(' + ')} +${selectedStyles.value.length-2}`
})
const activitySummary=computed(()=>!selectedActivities.value.length?'Choose what you usually dress for':selectedActivities.value.join(' · '))
function toggleStyle(style){error.value='';selectedStyles.value=selectedStyles.value.includes(style)?selectedStyles.value.filter(x=>x!==style):[...selectedStyles.value,style]}
function toggleActivity(a){selectedActivities.value=selectedActivities.value.includes(a)?selectedActivities.value.filter(x=>x!==a):[...selectedActivities.value,a]}
async function load(){try{const d=await getSurvey();selectedStyles.value=(d.survey.preferredStyles||[]).filter(s=>styleOptions.some(o=>o.name===s));selectedActivities.value=d.survey.activities||[];budget.value=d.survey.budget||40}catch(e){error.value=e.message}finally{loading.value=false}}
async function submit(){error.value='';if(selectedStyles.value.length<2)return error.value='Choose at least 2 styles so we can personalise your recommendations better.';if(!selectedActivities.value.length)return error.value='Choose at least one occasion you dress for.';busy.value=true;try{const r=await saveSurvey({preferredStyles:selectedStyles.value,activities:selectedActivities.value,budget:Number(budget.value)});authState.user=r.user;await router.push({name:'discover'})}catch(e){error.value=e.message}finally{busy.value=false}}
function skipForNow(){router.push({name:'discover'})}
load()
</script>
<template>
<section class="survey-page">
 <header class="survey-top"><RouterLink :to="{name:'discover'}" class="survey-logo">Dripped<span>✿</span></RouterLink><div class="survey-progress"><span class="active"></span><span></span><span></span><small>Personalise your Discover page</small></div><div class="survey-avatar">{{(authState.user?.name||'A').charAt(0).toUpperCase()}}</div></header>
 <main class="survey-wrap">
  <section class="survey-main">
   <p class="survey-eyebrow">MAKE DISCOVER FEEL LIKE YOU</p><h1>Tell us what you actually wear.</h1><p class="survey-lead">Three quick choices help us rank relevant pieces higher, without hiding the rest of the store.</p>
   <div v-if="loading" class="survey-loading">Loading your preferences…</div>
   <form v-else @submit.prevent="submit">
    <fieldset :disabled="busy"><div class="survey-section-head"><div><legend>1. Which styles feel like you?</legend><p>Choose at least 2. Select as many as you like.</p></div><span>{{selectedStyles.length}} selected</span></div>
      <div class="survey-style-grid"><button v-for="option in styleOptions" :key="option.name" type="button" class="survey-style-card" :class="{selected:selectedStyles.includes(option.name)}" :aria-pressed="selectedStyles.includes(option.name)" @click="toggleStyle(option.name)"><div class="survey-style-photo"><img :src="option.image" :alt="`${option.name} fashion inspiration`"/><span v-if="selectedStyles.includes(option.name)" class="survey-check">✓</span></div><div><strong>{{option.name}}</strong><small>{{option.desc}}</small></div></button></div>
    </fieldset>
    <fieldset :disabled="busy"><div class="survey-section-head"><div><legend>2. What are you usually dressing for?</legend><p>Select as many as apply. We use this to understand your real wardrobe needs.</p></div><span>{{selectedActivities.length}} selected</span></div>
      <div class="survey-occasion-grid"><button v-for="a in activities" :key="a" type="button" :class="{selected:selectedActivities.includes(a)}" :aria-pressed="selectedActivities.includes(a)" @click="toggleActivity(a)"><span class="occasion-check">{{selectedActivities.includes(a)?'✓':'+'}}</span>{{a}}</button></div>
    </fieldset>
    <fieldset :disabled="busy"><div class="survey-section-head"><div><legend>3. What feels comfortable per item?</legend><p>This is a recommendation preference, not a hard shopping limit.</p></div><strong class="survey-budget-value">Up to S${{budget}}</strong></div><div class="survey-range"><input v-model.number="budget" type="range" min="10" max="100" step="5" aria-label="Budget per item"/><div><span>S$10</span><span>S$40</span><span>S$70</span><span>S$100</span></div></div></fieldset>
    <p v-if="error" class="survey-error" role="alert">{{error}}</p>
    <div class="survey-actions"><button type="button" class="survey-skip" @click="skipForNow">Skip for now</button><button class="survey-save" :disabled="busy">{{busy?'Saving…':'Save & personalise Discover'}} <span>→</span></button></div>
   </form>
  </section>
  <aside class="survey-preview"><div class="survey-preview-sticky"><p class="survey-eyebrow">LIVE PREVIEW</p><h2>Your Discover profile</h2><p>These signals help us explain why a piece is being shown to you.</p><div class="survey-preview-art"><div class="preview-swatch one"></div><div class="preview-swatch two"></div><div class="preview-card-mini"><span>Picked for you</span><strong>{{previewHeadline}}</strong><small>within S${{budget}}</small></div></div><div class="survey-preview-row"><span>Style</span><div><em v-for="s in previewStyles" :key="s">{{s}}</em></div></div><div class="survey-preview-row"><span>Dressing for</span><strong>{{activitySummary}}</strong></div><div class="survey-preview-row"><span>Budget</span><strong>Up to S${{budget}} / item</strong></div><div class="survey-privacy"><span>✓</span><p><strong>You stay in control.</strong><br/>You can edit these preferences anytime from Discover.</p></div></div></aside>
 </main>
</section>
</template>
