26px #60384d12;border-color:#c6a7b6}.survey-style-card.selected{border:2px solid #6a3a5f;box-shadow:0 0 0 3px #f4e8ef}.survey-style-photo{position:relative;height:150px;background:#f1e7e2;overflow:hidden}.survey-style-photo img{width:100%;height:100%;object-fit:cover;object-position:center;filter:saturate(.72) contrast(.96);transform:scale(1.045);transition:.2s}.survey-style-card:hover img{transform:scale(1.075)}.survey-style-card>div:last-child{padding:13px 14px 14px}.survey-style-card strong{display:block;font-size:15px}.survey-style-card small{display:block;color:#766b73;font-size:11px;line-height:1.4;margin-top:4px}.survey-check{position:absolute;right:10px;top:10px;width:28px;height:28px;border-radius:50%;background:#613654;color:white;display:grid;place-items:center;font-weight:700}.survey-occasion-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.survey-occasion-grid button{display:flex;align-items:center;gap:9px;min-height:48px;padding:10px 13px;border:1px solid #e1d6dc;border-radius:12px;background:#fff;color:#433941;text-align:left}.survey-occasion-grid button.selected{background:#68405e;color:#fff;border-color:#68405e}.occasion-check{width:22px;height:22px;border-radius:50%;display:grid;place-items:center;background:#f2e8ed;color:#65405a;font-size:13px;flex:0 0 auto}.selected .occasion-check{background:#fff;color:#653c59}.survey-budget-value{font:600 24px Georgia,serif;color:#57264d}.survey-range input{width:100%;accent-color:#70405f}.survey-range>div{display:flex;justify-content:space-between;color:#8a7d86;font-size:11px;margin-top:5px}.survey-actions{display:flex;align-items:center;justify-content:flex-end;gap:14px;padding-top:6px;border-top:1px solid #eee4e7}.survey-save{min-height:52px;padding:0 26px;border:0;border-radius:11px;background:linear-gradient(120deg,#70425f,#5b3651);color:#fff;font-weight:650}.survey-skip{min-height:52px;border:0;background:transparent;color:#766675;padding:0 18px}.survey-error{background:#fff0f2;color:#8b2942;border:1px solid #f2c7d2;padding:11px 14px;border-radius:10px}.survey-preview-sticky{position:sticky;top:112px;border:1px solid #eadfe5;border-radius:22px;background:linear-gradient(155deg,#f8f0ff,#ffe9df);padding:28px;box-shadow:0 18px 50px #60384d0b}.survey-preview h2{font:500 30px Georgia,serif;color:#4d1c46;margin:0 0 7px}.survey-preview>div>p:not(.survey-eyebrow){color:#6f626b;line-height:1.5}.survey-preview-art{height:210px;margin:22px 0;border-radius:16px;background:#fff9;position:relative;overflow:hidden}.preview-swatch{position:absolute;border-radius:120px}.preview-swatch.one{width:190px;height:190px;background:#f5d9df;left:-55px;bottom:-65px}.preview-swatch.two{width:170px;height:170px;background:#ddd4f1;right:-50px;top:-50px}.preview-card-mini{position:absolute;inset:42px 32px;display:flex;flex-direction:column;justify-content:center;align-items:center;border-radius:15px;background:#fff;box-shadow:0 12px 30px #5f3c5012;text-align:center}.preview-card-mini span,.preview-card-mini small{font-size:11px;color:#8b7482}.preview-card-mini strong{font:600 27px Georgia,serif;color:#57254d;margin:7px}.survey-preview-row{padding:15px 0;border-top:1px solid #e4d8df}.survey-preview-row>span{display:block;color:#8a7783;font-size:11px;text-transform:uppercase;letter-spacing:.08em;margin-bottom:7px}.survey-preview-row em{display:inline-block;font-style:normal;background:#fff7fb;border-radius:999px;padding:6px 10px;font-size:12px;margin:0 5px 5px 0}.survey-preview-row strong{font-size:14px}.survey-privacy{display:flex;gap:10px;margin-top:18px;padding:13px;border-radius:12px;background:#fff9}.survey-privacy span{color:#4e784f}.survey-privacy p{margin:0!important;font-size:12px!important}.survey-loading{padding:30px;background:#fff;border-radius:16px}@media(max-width:1100px){.survey-wrap{grid-template-columns:1fr}.survey-preview{display:none}.survey-style-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:720px){.survey-progress{display:none}.survey-top{